previewCss:
.darma-loader-three-dots-typing{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-gap: calc(var(--loader-size, 56px) / 12);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--td-gap);
  width:var(--loader-size, 56px);
  height:var(--loader-size, 56px);
}
.darma-loader-three-dots-typing i{
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-color, #6366f1);
}
.darma-loader-three-dots-typing i{animation:darma-loader-three-dots-typing-td-typing var(--loader-speed, 1.5s) infinite linear}
.darma-loader-three-dots-typing i:nth-child(2){animation-delay:calc(var(--loader-speed, 1.5s) / 6)}
.darma-loader-three-dots-typing i:nth-child(3){animation-delay:calc(var(--loader-speed, 1.5s) / 3)}
@keyframes darma-loader-three-dots-typing-td-typing{
  0%,60%,100%{transform:translateY(0)}
  30%{transform:translateY(calc(var(--td-dot) * -1.1))}
}

